  setCells(cells              ,low       ,high       ){const vertices         =[];for(const c of cells){const v=Number.isFinite(c.value)?Math.max(0,Math.min(1,(c.value-low)/(high-low))):-1;vertices.push(c.x0,c.y0,v,c.x0,c.y1,v,c.x1,c.y0,v,c.x1,c.y0,v,c.x0,c.y1,v,c.x1,c.y1,v)}this.meshVertices=vertices.length/3;this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.meshBuffer);this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(vertices),this.gl.DYNAMIC_DRAW);this.draw()}
