          async loadCoastlines(){const world=await fetch('world.geojson').then(r=>r.json())                                                             ,lines         =[];const add=(ring           )=>{for(let i=1;i<ring.length;i++){const a=ring[i-1],b=ring[i];if(Math.abs(a[0]-b[0])<180)lines.push(a[0]/180,a[1]/90,b[0]/180,b[1]/90)}};for(const f of world.features){const g=f.geometry;if(g.type==='Polygon')for(const ring of g.coordinates                )add(ring);if(g.type==='MultiPolygon')for(const polygon of g.coordinates                  )for(const ring of polygon)add(ring)}this.lineVertices=lines.length/2;this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.lineBuffer);this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(lines),this.gl.STATIC_DRAW);this.draw()}
          scale(){const width=Math.max(1,this.canvas.clientWidth),height=Math.max(1,this.canvas.clientHeight),ratio=Math.min(2,window.devicePixelRatio||1);if(this.canvas.width!==Math.round(width*ratio)||this.canvas.height!==Math.round(height*ratio)){this.canvas.width=Math.round(width*ratio);this.canvas.height=Math.round(height*ratio)}const aspect=width/height;return aspect>2?[2/aspect,1]:[1,aspect/2]}
